  const HIT_MASK_W = 160;
  const HIT_MASK_H = 90;
  const VEHICLE_HIT_MASKS = {"traktor":"","villamos":"","hev":"","hokotro":"","pickup":"","police-suv":"","police-sedan":"","blue-sedan":"","kiss":"","firetruck":"","ambulance":"","black-offroad":"","white-suv":"","pink-cabrio":"","blue-bus":"","yellow-truck":"","grey-truck":"","crane-truck":"","microcar":"","tow-truck":"","garbage-truck":"","excavator":"","monster-truck":"","mixer":"","street-sweeper":"","forklift":"","sportscar":"","camper":"","wagon":"","combine":""};
  const vehicleHitMaskCache = new Map();

  function hitMaskBytes(vehicleId){
    if(vehicleHitMaskCache.has(vehicleId)) return vehicleHitMaskCache.get(vehicleId);
    const encoded = VEHICLE_HIT_MASKS[vehicleId];
    if(!encoded) return null;
    const raw = atob(encoded);
    const bytes = new Uint8Array(raw.length);
    for(let i=0;i<raw.length;i++) bytes[i]=raw.charCodeAt(i);
    vehicleHitMaskCache.set(vehicleId,bytes);
    return bytes;
  }

  function pointerHitsVehicle(vehicle, img, evt){
    if(!vehicle || !img) return false;
    const rect = img.getBoundingClientRect();
    if(evt.clientX < rect.left || evt.clientX > rect.right || evt.clientY < rect.top || evt.clientY > rect.bottom) return false;
    const u = (evt.clientX - rect.left) / Math.max(1, rect.width);
    const v = (evt.clientY - rect.top) / Math.max(1, rect.height);
    const x = clamp(Math.floor(u * HIT_MASK_W), 0, HIT_MASK_W-1);
    const y = clamp(Math.floor(v * HIT_MASK_H), 0, HIT_MASK_H-1);
    const idx = y * HIT_MASK_W + x;
    const bytes = hitMaskBytes(vehicle.id);
    return !!(bytes && ((bytes[idx >> 3] >> (idx & 7)) & 1));
  }

