function formatStopwatch(ms) {
  if (!Number.isFinite(ms) || ms <= 0) return '00:00.0';
  const totalTenths = Math.floor(ms / 100);
  const minutes = Math.floor(totalTenths / 600);
  const seconds = Math.floor((totalTenths % 600) / 10);
  const tenths = totalTenths % 10;
  return `${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}.${tenths}`;
}

function loadBestWashTime() {
  try {
    let best = 0;
    for (const key of FASTEST_TIME_KEYS) {
      const raw = localStorage.getItem(key);
      const value = raw ? Number(raw) : 0;
      if (Number.isFinite(value) && value > 0 && (!best || value < best)) best = value;
    }
    return best;
  } catch (_) {
    return 0;
  }
}

function saveBestWashTime(ms) {
  if (!Number.isFinite(ms) || ms <= 0) return;
  bestWashTime = ms;
  try {
    FASTEST_TIME_KEYS.forEach(key => localStorage.setItem(key, String(ms)));
  } catch (_) {}
  updateBestTimeUI();
}

function updateBestTimeUI() {
  if (!bestTimeValue) return;
  const storedBest = loadBestWashTime();
  if (storedBest > 0 && (!bestWashTime || storedBest < bestWashTime)) bestWashTime = storedBest;
  bestTimeValue.textContent = bestWashTime > 0 ? formatStopwatch(bestWashTime) : '--:--.-';
  bestTimeValue.setAttribute('data-best-ms', bestWashTime > 0 ? String(Math.round(bestWashTime)) : '0');
}

function updateTimerUI(force=false) {
  if (!timerDisplay) return;
  const value = washTimerRunning ? (performance.now() - washTimerStartedAt) : washTimerElapsed;
  if (force || washTimerRunning || washTimerElapsed === 0) {
    timerDisplay.textContent = formatStopwatch(value);
  }
}

function startWashTimer() {
  if (washTimerRunning) return;
  washTimerStartedAt = performance.now();
  washTimerElapsed = 0;
  washTimerRunning = true;
  updateTimerUI(true);
}

function stopWashTimer() {
  if (!washTimerRunning) return washTimerElapsed;
  washTimerElapsed = Math.max(0, performance.now() - washTimerStartedAt);
  washTimerRunning = false;
  updateTimerUI(true);
  return washTimerElapsed;
}

function resetWashTimer() {
  washTimerStartedAt = 0;
  washTimerElapsed = 0;
  washTimerRunning = false;
  updateTimerUI(true);
}

