  function updateCarouselUI() {
    const cards = [...carouselTrack.querySelectorAll('.carousel-vehicle')];
    const vw = carouselViewport ? carouselViewport.clientWidth : window.innerWidth;
    const step = Math.max(340, vw);
    cards.forEach((card, i) => {
      const delta = i - carouselIndex;
      const abs = Math.abs(delta);
      const x = delta * step;
      const scale = abs === 0 ? 1 : abs === 1 ? .62 : .48;
      const opacity = abs === 0 ? 1 : abs === 1 ? .72 : .18;
      card.style.transform = `translateX(calc(-50% + ${x}px)) scale(${scale})`;
      card.style.opacity = opacity;
      card.style.zIndex = String(20 - Math.min(abs, 9));
      card.classList.toggle('current', abs === 0);
      if (abs !== 0 || !carouselArmed) card.classList.remove('ready');
    });
    [...carouselDots.children].forEach((d,i)=>d.classList.toggle('active', i===carouselIndex));
  }

